import React, { useContext, useState } from "react";
import { authContext } from "../../context/authContext";
import userImg from "../../assets/images/doctor-img01.png";
import MyBookings from "./MyBookings";
import Profile from "./Profile";
import useGetProfileData from "../../hooks/useFetchData";
import Loading from "../../components/Loader/Loading";
import Error from "../../components/Error/Error";

const MyAccount = () => {
  const base_url = process.env.REACT_APP_BASE_URL;
  const { dispatch } = useContext(authContext);
  const [tab, setTab] = useState("bookings");
  const {
    data: userData,
    loading,
    error,
  } = useGetProfileData(`${base_url}/users/profile/me`);
  const handleLogout = () => {
    dispatch({
      type: "LOGOUT",
    });
  };
  console.log("user", userData);
  return (
    <section>
      <div className="max-w-[1170px] px-5 mx-auto ">
        {loading && !error && <Loading />}
        {error && !loading && <Error errMessage={error} />}
        {!loading && !error && (
          <div className="grid md:grid-cols-3 gap-10 ">
            <div className="pb-[50px] px-[30px] rounded-md ">
              <div className="flex items-center justify-center">
                <figure className="w-[100px] h-[100px] rounded-full border-2 border-solid border-primaryColor ">
                  <img
                    src={userData["data"]?.photo}
                    alt=""
                    className="w-full h-full rounded-full"
                  />
                </figure>
              </div>
              <div className="text-center mt-4">
                <h3 className="text-[18px] leading-[30px] text-headingColor font-bold ">
                  {userData["data"]?.name}
                </h3>
                <p className="text-textColor text-[15px] leading-6 font-medium ">
                  {userData["data"]?.email}
                </p>
                <p className="text-textColor text-[15px] leading-6 font-medium ">
                  Blood Type:{" "}
                  <span className="ml-2 text-headingColor text-[22px] leading-8">
                    {userData["data"]?.bloodType}
                  </span>
                </p>
              </div>
              <div className="mt-[50px] md:mt-[100px] ">
                <button
                  onClick={handleLogout}
                  className="w-full p-3 text-[16px] leading-7 rounded-md text-white bg-[#181A1E] "
                >
                  Logout
                </button>
                <button className="w-full mt-4 p-3 text-[16px] leading-7 rounded-md text-white bg-red-600 ">
                  Delete Account
                </button>
              </div>
            </div>
            <div className="md:col-span-2 md:px-[30px]">
              <div>
                <button
                  onClick={() => setTab("bookings")}
                  className={`${
                    tab === "bookings" &&
                    "bg-primaryColor text-white font-normal"
                  } p-2 mr-5 px-5 rounded-md text-headingColor font-semibold text-[16px] leading-7 border border-solid border-primaryColor `}
                >
                  My Bookings
                </button>
                <button
                  onClick={() => setTab("settings")}
                  className={`${
                    tab === "settings" &&
                    "bg-primaryColor text-white font-normal"
                  } p-2 mr-5 px-5 rounded-md text-headingColor font-semibold text-[16px] leading-7 border border-solid border-primaryColor `}
                >
                  Profile Settings
                </button>
              </div>
              {tab === "settings" && <Profile user={userData} />}
              {tab === "bookings" && <MyBookings />}
            </div>
          </div>
        )}
      </div>
    </section>
  );
};

export default MyAccount;
