import React, { useState } from "react";
import doctorsImg from "../../assets/images/doctor-img02.png";
import starIcon from "../../assets/images/Star.png";
import Doctors from "./Doctors";
import DoctorsAbout from "./DoctorsAbout";
import Feedback from "./Feedback";
import SidePanel from "./SidePanel";
import useFetchData from "../../hooks/useFetchData";
import Loader from "../../components/Loader/Loading";
import Error from "../../components/Error/Error";
import axios from "axios";
import { useParams } from "react-router-dom";

const DoctorDetails = () => {
  const base_url = process.env.REACT_APP_BASE_URL;
  const [tab, setTab] = useState("about");
  const { id } = useParams();
  const {
    data: doctors,
    loading,
    error,
  } = useFetchData(`${base_url}/doctors/${id}`);

  const {
    name,
    qualifications,
    experiences,
    timeSlots,
    reviews,
    bio,
    about,
    averageRating,
    totalRating,
    specialization,
    ticketPrice,
    photo,
  } = doctors?.data || {};

  console.log("doct:", doctors?.data);
  return (
    <section>
      <div className="max-w-[1170px] px-5 mx-auto">
        <div className="grid md:grid-cols-3 gap-[50px]">
          <div className="md:col-span-2">
            <div className="flex items-center gap-5">
              <figure className="max-w-[200px] max-h-[200px] ">
                <img className="w-full" src={doctorsImg} alt="" />
              </figure>
              <div>
                <span className="bg-[#CCF0F3] text-irisBlueColor py-1 px-6  lg:py-2 lg:px-6 text-[12px] lg:text-[16px] leading-4 lg:leadin-7 font-semibold rounded  ">
                  {specialization}
                </span>
                <h3 className="text-headingColor mt-3 font-bold leading-9 text-[22px] ">
                  {name}
                </h3>
                <div className="flex items-center gap-[6px]">
                  <span className="flex items-center gap-[6px] text-[14px] leading-6 lg:text-[16px] lg:leading-7 font-semibold text-headingColor ">
                    <img src={starIcon} alt="" /> {averageRating}
                  </span>
                  <span className="text-[14px] leading-6 lg:text-[16px] leading-4 lg:leading-7 font-[400] text-textColor ">
                    ({totalRating})
                  </span>
                </div>
                <p className="text_para text-[14px] md:text-[15px] leading-6 lg:max-w-[390px] ">
                  {bio}
                </p>
              </div>
            </div>
            <div className="mt-[50px] border-b border-solid border-[#0066ff34]  ">
              <button
                onClick={() => setTab("about")}
                className={`${
                  tab === "about" &&
                  "border-b border-solid border-primaryColor "
                } py-2 px-5 mr-5 text-[16px] leading-7 text-headingColor font-semibold `}
              >
                About
              </button>
              <button
                onClick={() => setTab("feedback")}
                className={`${
                  tab === "feedback" &&
                  "border-b border-solid border-primaryColor "
                } py-2 px-5 mr-5 text-[16px] leading-7 text-headingColor font-semibold `}
              >
                Feedback
              </button>
            </div>
            <div className="mt-[50px]">
              {tab === "about" && (
                <DoctorsAbout
                  name={name}
                  about={about}
                  qualification={qualifications}
                  experience={experiences}
                />
              )}
              {tab === "feedback" && (
                <Feedback reviews={reviews} totalRating={totalRating} />
              )}
            </div>
          </div>
          <div>
            <SidePanel
              doctorId={doctors?.data?._id}
              ticketPrice={ticketPrice}
              timeSlots={timeSlots}
            />
          </div>
        </div>
      </div>
    </section>
  );
};

export default DoctorDetails;
